void Solver::rephase() {
    // Reset the rephase counter so the new phases can take effect immediately
    rephases = 0;

    // Make the next rephase trigger a bit earlier when the search is deep
    // Reduce the threshold more aggressively but never below the current trail size
    threshold = std::max((int)(threshold * 0.85), (int)trail.size());

    // Grow the rephase limit gradually (add 25% of the current limit)
    rephase_limit += (rephase_limit >> 2);

    // Choose a new phase‑saving strategy
    int strategy = rand() % 4;
    for (int i = 1; i <= vars; ++i) {
        if (strategy == 0) {
            // Use the best phase seen so far
            saved[i] = local_best[i];
        } else if (strategy == 1) {
            // Use the opposite of the best phase
            saved[i] = -local_best[i];
        } else if (strategy == 2) {
            // Randomly assign a polarity
            saved[i] = (rand() & 1) ? 1 : -1;
        } else {
            // Keep the previous saved polarity, but flip it with a small probability
            if (rand() % 10 == 0) saved[i] = -saved[i];
        }
    }

    // Apply the new phases by backtracking to the root level
    backtrack(0);
}
